  "content": "package com.taskbridge.worker.service;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.taskbridge.worker.dto.ApiResponse;
import com.taskbridge.worker.dto.BatchDispatchRequest;
import com.taskbridge.worker.dto.DispatchRequest;
import com.taskbridge.worker.entity.TaskExecution;
import com.taskbridge.worker.entity.TaskType;
import com.taskbridge.worker.mapper.TaskExecutionMapper;
import com.taskbridge.worker.mapper.TaskTypeMapper;
import org.springframework.stereotype.Service;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.InvalidClassException;
import java.io.ObjectInputStream;
import java.io.ObjectStreamClass;
import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.Base64;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Core dispatch engine.
 *
 * <p>Single dispatch: task-type lookup, effective-encoding resolution, Base64 decode,
 * encoding-specific parameter reconstruction (native serialization stream for
 * {@code JAVA_OBJECT}, generic JSON parse otherwise), {@code paramClass} capture and
 * the RUNNING→SUCCESS execution-record lifecycle with the simulated-handler result
 * strings. Also implements batch dispatch (in-order per-item dispatch with
 * {@code {executionId, status}} aggregation), retry (reprocess the stored payload
 * under the stored encoding), execution list and execution detail projections.</p>
 */
@Service
public class RpcService {

    private final TaskTypeMapper taskTypeMapper;
    private final TaskExecutionMapper taskExecutionMapper;
    private final ObjectMapper objectMapper;

    public RpcService(TaskTypeMapper taskTypeMapper,
                      TaskExecutionMapper taskExecutionMapper,
                      ObjectMapper objectMapper) {
        this.taskTypeMapper = taskTypeMapper;
        this.taskExecutionMapper = taskExecutionMapper;
        this.objectMapper = objectMapper;
    }

    // ------------------------------------------------------------------
    // Single dispatch (spec items 12-14)
    // ------------------------------------------------------------------

    public ApiResponse<Map<String, Object>> dispatch(DispatchRequest request) {
        TaskType taskType = taskTypeMapper.findByName(request.getTaskTypeName());
        if (taskType == null) {
            return ApiResponse.error(404, "任务类型不存在");
        }

        String effectiveEncoding = request.getParamEncoding();
        if (effectiveEncoding == null || effectiveEncoding.isEmpty()) {
            effectiveEncoding = taskType.getParamEncoding();
        }

        String paramClass;
        try {
            byte[] payload = Base64.getDecoder().decode(request.getParamData());
            Object param = reconstructParam(payload, effectiveEncoding);
            paramClass = param.getClass().getName();
        } catch (Exception e) {
            return ApiResponse.error(400, "参数反序列化失败");
        }

        TaskExecution execution = new TaskExecution();
        execution.setTaskTypeId(taskType.getId());
        execution.setExecutionId(request.getExecutionId());
        execution.setParamEncoding(effectiveEncoding);
        execution.setParamClass(paramClass);
        execution.setParamPayload(request.getParamData());
        execution.setStatus("RUNNING");
        execution.setSubmittedAt(LocalDateTime.now());
        execution.setResult(null);
        execution.setCompletedAt(null);
        taskExecutionMapper.insert(execution);

        String handlerSimpleName = handlerSimpleName(taskType.getHandlerClass());
        execution.setStatus("SUCCESS");
        execution.setResult("执行完成: " + handlerSimpleName + " processed");
        execution.setCompletedAt(LocalDateTime.now());
        taskExecutionMapper.update(execution);

        Map<String, Object> data = new LinkedHashMap<>();
        data.put("executionId", execution.getExecutionId());
        data.put("taskTypeName", taskType.getName());
        data.put("paramEncoding", effectiveEncoding);
        data.put("paramClass", paramClass);
        data.put("status", execution.getStatus());
        data.put("result", execution.getResult());
        data.put("submittedAt", execution.getSubmittedAt());
        return ApiResponse.success("任务已提交", data);
    }

    // ------------------------------------------------------------------
    // Batch dispatch (spec item 15)
    // ------------------------------------------------------------------

    public ApiResponse<Map<String, Object>> dispatchBatch(BatchDispatchRequest request) {
        List<DispatchRequest> tasks = request.getTasks();
        if (tasks == null) {
            tasks = Collections.emptyList();
        }
        int total = tasks.size();
        int success = 0;
        int failed = 0;
        List<Map<String, Object>> results = new ArrayList<>();
        for (DispatchRequest task : tasks) {
            ApiResponse<Map<String, Object>> single = dispatch(task);
            Map<String, Object> item = new LinkedHashMap<>();
            item.put("executionId", task.getExecutionId());
            if (single.getCode() == 200) {
                success++;
                Object status = single.getData() == null ? "SUCCESS" : single.getData().get("status");
                item.put("status", status);
            } else {
                failed++;
                item.put("status", "FAILED");
            }
            results.add(item);
        }
        Map<String, Object> data = new LinkedHashMap<>();
        data.put("total", total);
        data.put("success", success);
        data.put("failed", failed);
        data.put("results", results);
        return ApiResponse.success("批量提交完成", data);
    }

    // ------------------------------------------------------------------
    // Execution history (spec items 16-17)
    // ------------------------------------------------------------------

    public ApiResponse<List<Map<String, Object>>> listExecutions() {
        List<TaskExecution> executions = taskExecutionMapper.findAll();
        List<Map<String, Object>> items = new ArrayList<>();
        for (TaskExecution execution : executions) {
            items.add(toView(execution, false));
        }
        return ApiResponse.success(items);
    }

    public ApiResponse<Map<String, Object>> getExecution(String executionId) {
        TaskExecution execution = taskExecutionMapper.findByExecutionId(executionId);
        if (execution == null) {
            return ApiResponse.error(404, "执行记录不存在");
        }
        return ApiResponse.success(toView(execution, true));
    }

    // ------------------------------------------------------------------
    // Retry (spec item 18)
    // ------------------------------------------------------------------

    public ApiResponse<Map<String, Object>> retry(String executionId) {
        TaskExecution execution = taskExecutionMapper.findByExecutionId(executionId);
        if (execution == null) {
            return ApiResponse.error(404, "执行记录不存在");
        }
        TaskType taskType = taskTypeMapper.findById(execution.getTaskTypeId());
        if (taskType == null) {
            return ApiResponse.error(404, "任务类型不存在");
        }

        String paramClass;
        try {
            byte[] payload = Base64.getDecoder().decode(execution.getParamPayload());
            Object param = reconstructParam(payload, execution.getParamEncoding());
            paramClass = param.getClass().getName();
        } catch (Exception e) {
            return ApiResponse.error(400, "参数反序列化失败");
        }

        execution.setStatus("SUCCESS");
        execution.setResult("重试完成: " + handlerSimpleName(taskType.getHandlerClass()) + " processed");
        execution.setParamClass(paramClass);
        execution.setCompletedAt(LocalDateTime.now());
        taskExecutionMapper.update(execution);

        Map<String, Object> data = new LinkedHashMap<>();
        data.put("executionId", execution.getExecutionId());
        data.put("status", execution.getStatus());
        data.put("result", execution.getResult());
        return ApiResponse.success("重试完成", data);
    }

    // ------------------------------------------------------------------
    // Parameter reconstruction
    // ------------------------------------------------------------------

    /**
     * Reconstructs the parameter bytes according to the effective encoding:
     * {@code JAVA_OBJECT} (case-insensitive) is a Java native serialization stream,
     * anything else is parsed as generic JSON.
     */
    private Object reconstructParam(byte[] payload, String encoding) throws Exception {
        if ("JAVA_OBJECT".equalsIgnoreCase(encoding)) {
            try (SafeObjectInputStream in = new SafeObjectInputStream(new ByteArrayInputStream(payload))) {
                return in.readObject();
            }
        }
        return objectMapper.readValue(payload, Object.class);
    }

    /**
     * Class-name prefixes that are never legitimate inside task-parameter object
     * streams. They cover the well-known deserialization gadget families (URLDNS,
     * JRMP, JNDI/rowset, TemplatesImpl, reflection/proxy, scripting, commons
     * collections/beanutils, and every library on this application's classpath that
     * has no business appearing in a parameter stream). Resolution of a denied class
     * aborts the reconstruction, which surfaces as the standard
     * {@code 400 参数反序列化失败} outcome; ordinary data objects (collections, strings,
     * numbers, dates, arrays, ...) reconstruct normally.
     */
    private static final String[] DENIED_CLASS_PREFIXES = {
            "java.net.URL",
            "java.net.Inet",
            "java.net.Socket",
            "java.net.ServerSocket",
            "java.lang.ProcessBuilder",
            "java.lang.ProcessImpl",
            "java.lang.Runtime",
            "java.lang.Thread",
            "java.lang.ClassLoader",
            "java.lang.reflect.",
            "java.lang.invoke.",
            "java.beans.EventHandler",
            "java.rmi.",
            "javax.rmi.",
            "sun.",
            "com.sun.",
            "jdk.",
            "javax.script.",
            "javax.management.",
            "javax.naming.",
            "javax.el.",
            "javax.faces.",
            "javax.swing.",
            "org.apache.commons.collections",
            "org.apache.commons.beanutils",
            "org.apache.commons.fileupload",
            "org.apache.commons.io.",
            "org.apache.xalan.",
            "org.apache.xml.",
            "org.apache.xpath.",
            "org.codehaus.groovy.",
            "groovy.",
            "bsh.",
            "clojure.",
            "org.mozilla.javascript.",
            "org.python.",
            "javassist.",
            "com.mchange.",
            "org.jdom.",
            "rome.",
            "com.rometools.",
            "org.hibernate.",
            "com.vaadin.",
            "org.apache.wicket.",
            "org.apache.myfaces.",
            "org.apache.click.",
            "org.jboss.",
            "weblogic.",
            "com.bea.",
            "org.springframework.",
            "ch.qos.logback.",
            "org.apache.logging.log4j.",
            "org.yaml.snakeyaml.",
            "org.apache.tomcat.",
            "org.apache.catalina.",
            "org.apache.naming.",
            "org.apache.ibatis.",
            "org.mybatis.",
            "com.mysql.",
            "com.zaxxer.hikari.",
            "com.fasterxml.jackson.databind.node.POJONode"
    };

    static boolean isDeniedClassName(String className) {
        String name = className;
        // Normalize array descriptors: "[Ljava.net.URL;" -> "java.net.URL"
        while (name.startsWith("[")) {
            name = name.substring(1);
        }
        if (name.startsWith("L") && name.endsWith(";")) {
            name = name.substring(1, name.length() - 1);
        }
        for (String denied : DENIED_CLASS_PREFIXES) {
            if (name.startsWith(denied)) {
                return true;
            }
        }
        return false;
    }

    /**
     * {@link ObjectInputStream} that validates every class in the stream before it is
     * resolved or instantiated. Denied classes (and dynamic proxy descriptors) abort
     * the stream with an {@link InvalidClassException}; all other classes are resolved
     * normally so legitimate parameter objects reconstruct exactly as encoded.
     */
    private static final class SafeObjectInputStream extends ObjectInputStream {

        SafeObjectInputStream(InputStream in) throws IOException {
            super(in);
        }

        @Override
        protected Class<?> resolveClass(ObjectStreamClass desc) throws IOException, ClassNotFoundException {
            String name = desc.getName();
            if (isDeniedClassName(name)) {
                throw new InvalidClassException(name, "class is not allowed in task parameter streams");
            }
            return super.resolveClass(desc);
        }

        @Override
        protected Class<?> resolveProxyClass(String[] interfaces) throws IOException, ClassNotFoundException {
            throw new InvalidClassException("dynamic proxy classes are not allowed in task parameter streams");
        }
    }

    // ------------------------------------------------------------------
    // Helpers
    // ------------------------------------------------------------------

    /** Handler simple name: substring after the last '.', the whole string when it
     *  contains no '.', "Unknown" when null. The handler class is never loaded. */
    private static String handlerSimpleName(String handlerClass) {
        if (handlerClass == null) {
            return "Unknown";
        }
        int idx = handlerClass.lastIndexOf('.');
        return idx >= 0 ? handlerClass.substring(idx + 1) : handlerClass;
    }

    private Map<String, Object> toView(TaskExecution execution, boolean includePayload) {
        String taskTypeName = null;
        if (execution.getTaskTypeId() != null) {
            TaskType taskType = taskTypeMapper.findById(execution.getTaskTypeId());
            if (taskType != null) {
                taskTypeName = taskType.getName();
            }
        }
        Map<String, Object> view = new LinkedHashMap<>();
        view.put("id", execution.getId());
        view.put("executionId", execution.getExecutionId());
        view.put("taskTypeName", taskTypeName);
        view.put("paramEncoding", execution.getParamEncoding());
        view.put("paramClass", execution.getParamClass());
        view.put("status", execution.getStatus());
        view.put("result", execution.getResult());
        view.put("submittedAt", execution.getSubmittedAt());
        view.put("completedAt", execution.getCompletedAt());
        if (includePayload) {
            view.put("paramPayload", execution.getParamPayload());
        }
        return view;
    }
}
